#include <Arduino.h>
#include <IRremote.hpp>
#include <Adafruit_GFX.h>
#include <Adafruit_ST7735.h>
#include <SPI.h>

// --- PIN TANIMLARI (BAĞLANTI TABLOSUYLA BİREBİR AYNI) ---
#define TFT_CS          5   // TFT CS Pin
#define TFT_RST         4   // TFT RESET Pin
#define TFT_DC          2   // TFT A0 / DC Pin
// TFT SDA -> GPIO 23 (ESP32 Donanımsal MOSI)
// TFT SCK -> GPIO 18 (ESP32 Donanımsal SCK)

#define TRIG_PIN        12  // Ultrasonik Sensör Tetik
#define ECHO_PIN        13  // Ultrasonik Sensör Yankı

#define IR_RECEIVE_PIN  15  // IR Alıcı Data/Out

#define BUZZER_PIN      19  // Pasif Buzzer S/Signal

#define RGB_RED_PIN     16  // RGB LED Kırmızı
#define RGB_GREEN_PIN   17  // RGB LED Yeşil
#define RGB_BLUE_PIN    21  // RGB LED Mavi

// --- EKRAN SÜRÜCÜSÜ ---
Adafruit_ST7735 tft = Adafruit_ST7735(TFT_CS, TFT_DC, TFT_RST);

// --- DEĞİŞKENLER ---
bool sistemAktif = false;   // Alarm kurulu mu?
bool alarmSiren = false;    // Hareket algılandı mı?
const int MESAFE_ESIK = 50; // Algılama mesafesi (cm)

// RGB LED Renk Fonksiyonu
void setRGB(bool r, bool g, bool b) {
  digitalWrite(RGB_RED_PIN, r ? HIGH : LOW);
  digitalWrite(RGB_GREEN_PIN, g ? HIGH : LOW);
  digitalWrite(RGB_BLUE_PIN, b ? HIGH : LOW);
}

// ST7735 TFT Ekran Arayüz Fonksiyonu
void tftEkranGuncelle(String durum, uint16_t renk, int mesafe) {
  tft.fillScreen(ST77XX_BLACK);

  // Üst Başlık
  tft.setCursor(10, 10);
  tft.setTextColor(ST77XX_WHITE);
  tft.setTextSize(1);
  tft.println("GUVENLIK SISTEMI");
  tft.drawFastHLine(0, 25, 160, ST77XX_WHITE);

  // Sistem Durumu
  tft.setCursor(10, 40);
  tft.setTextColor(renk);
  tft.setTextSize(2);
  tft.println(durum);

  // Anlık Mesafe
  tft.setCursor(10, 85);
  tft.setTextColor(ST77XX_YELLOW);
  tft.setTextSize(1);
  tft.print("MESAFE: ");
  if (mesafe > 0 && mesafe < 400) {
    tft.print(mesafe);
    tft.println(" cm");
  } else {
    tft.println("---");
  }
}

// HC-SR04 Mesafe Ölçüm Fonksiyonu
long mesafeOlc() {
  digitalWrite(TRIG_PIN, LOW);
  delayMicroseconds(2);
  digitalWrite(TRIG_PIN, HIGH);
  delayMicroseconds(10);
  digitalWrite(TRIG_PIN, LOW);

  long sure = pulseIn(ECHO_PIN, HIGH, 30000); // 30ms zamanaşımı
  if (sure == 0) return 999;
  return sure * 0.034 / 2;
}

void setup() {
  Serial.begin(115200);

  // Pin Yönlendirmeleri
  pinMode(TRIG_PIN, OUTPUT);
  pinMode(ECHO_PIN, INPUT);
  pinMode(BUZZER_PIN, OUTPUT);
  pinMode(RGB_RED_PIN, OUTPUT);
  pinMode(RGB_GREEN_PIN, OUTPUT);
  pinMode(RGB_BLUE_PIN, OUTPUT);

  // IR Alıcı Başlatma
  IrReceiver.begin(IR_RECEIVE_PIN, ENABLE_LED_FEEDBACK);

  // ST7735 TFT Ekran Başlatma
  tft.initR(INITR_BLACKTAB); // Redtab / Blacktab uyumlu başlangıç
  tft.setRotation(1);        // Yatay mod (128x160)

  // Başlangıç Durumu: PASİF
  tftEkranGuncelle("PASIF", ST77XX_BLUE, 0);
  setRGB(false, false, true); // Mavi LED
}

void loop() {
  long mesafe = mesafeOlc();

  // 1. IR KUMANDA KONTROLÜ
  if (IrReceiver.decode()) {
    // Alarm çalıyorsa kumandadan herhangi bir tuşa basınca susturur
    if (alarmSiren) {
      alarmSiren = false;
      noTone(BUZZER_PIN);
      tftEkranGuncelle("AKTIF", ST77XX_GREEN, mesafe);
      setRGB(false, true, false);
    } 
    // Alarm çalmıyorsa AÇ / KAPA (Sistemi Kur / Pasif Yap)
    else {
      sistemAktif = !sistemAktif;
      if (sistemAktif) {
        tftEkranGuncelle("AKTIF", ST77XX_GREEN, mesafe);
        setRGB(false, true, false); // Yeşil LED
      } else {
        tftEkranGuncelle("PASIF", ST77XX_BLUE, mesafe);
        setRGB(false, false, true); // Mavi LED
      }
    }
    IrReceiver.resume(); // Yeni sinyal için sıfırla
  }

  // 2. HAREKET ALGILAMA MANTIĞI
  if (sistemAktif && mesafe < MESAFE_ESIK && mesafe > 2) {
    if (!alarmSiren) {
      alarmSiren = true;
      tftEkranGuncelle("HAREKET!", ST77XX_RED, mesafe);
    }
  }

  // 3. PASİF BUZZER & RGB UYARI SİRENİ
  if (alarmSiren) {
    setRGB(true, false, false); // Kırmızı LED

    // Pasif Buzzer ile Yüksek Sesli Siren Efekti
    for (int hz = 800; hz < 2000; hz += 150) {
      tone(BUZZER_PIN, hz);
      delay(8);
    }
    for (int hz = 2000; hz > 800; hz -= 150) {
      tone(BUZZER_PIN, hz);
      delay(8);
    }
  } else {
    noTone(BUZZER_PIN);
    delay(100);
  }
}
